def test_invalid_incomplete(self):
    with self.assertRaises(ValueError):
        list(mi.grouper('ABCD', 3, incomplete='bogus'))

def test_strict_fails(self):
    seq = 'ABCDEF'
    for n in [4, 5, 7]:
        with self.subTest(n=n):
            with self.assertRaises(ValueError):
                list(mi.grouper(iter(seq), n, incomplete='strict'))
